<?php if(!$rows):?><p class="butchery-empty">Aucune demande dans cette sélection.</p><?php else:?><div class="table-responsive"><table class="enterprise-table" <?=$filters?'data-butchery-history="cancellations"':''?>><thead><tr><th>Demande / date</th><th>Site</th><th>Opération</th><th>Demandeur</th><th>Statut</th><th>Contre-opération</th><th>Détails</th></tr></thead><tbody><?php foreach($rows as $r):?><tr data-status="<?=e($r['status'])?>" data-date="<?=e(substr($r['requested_at'],0,10))?>"><td><strong><?=e($r['request_number'])?></strong><small><?=e($date($r['requested_at']))?></small></td><td><?=e($r['site_code'])?></td><td><?=e($r['label'].' #'.$r['entity_id'])?></td><td><?=e($r['requester_name'])?></td><td><span class="butchery-status"><?=e($labels[$r['status']]??$r['status'])?></span></td><td><?=e($r['reversal_number']?:'—')?></td><td><button type="button" class="btn-secondary" data-workspace-modal-open="cancellation-detail-<?=e($r['id'])?>">Examiner</button></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
